using System;
using NUnit.Framework;

namespace PeroTools2.Error.Tests;

/// <summary>Every companion class declared here is generated by PeroTools2.PeroError.Generator</summary>
internal enum CompanionErrKind
{
    /// <summary>Generates <c>CompanionErrKind_NotFound</c></summary>
    [ErrMsg("File {path} Do Not Exist")]
    [ErrArg("path", typeof(string), "Path that was not found")]
    NotFound,

    /// <summary>Generates <c>CompanionErrKind_Timeout</c> with two arguments and a format specifier</summary>
    [ErrMsg("Read {path} Timeout After {timeout:F2}s")]
    [ErrArg("path", typeof(string), "Path that timed out")]
    [ErrArg("timeout", typeof(double), "Timeout in seconds")]
    Timeout,

    /// <summary>No arguments; only verifies escaping of braces, quotes and backslashes</summary>
    [ErrMsg("Literal {{brace}}, quote \" and back\\slash")]
    Escaped,

    /// <summary>The argument name is itself a C# keyword</summary>
    [ErrMsg("event = {event}")]
    [ErrArg("event", typeof(string), "Event name")]
    Keyword,

    /// <summary>Custom generated class name</summary>
    [ErrMsg("custom named {value}", Name = nameof(CustomNamedCompanion))]
    [ErrArg("value", typeof(int), "Custom class name")]
    CustomNamed,
}

[TestFixture]
[TestOf(typeof(Err<>))]
public sealed class ErrCompanionTests
{
    private static string CurrentMember([System.Runtime.CompilerServices.CallerMemberName] string member = null) => member;

    [Test]
    public void GeneratedClassShapeTest()
    {
        var type = typeof(CompanionErrKind_NotFound);

        Assert.That(type.IsClass, Is.True);
        Assert.That(type.IsSealed, Is.True);
        // The enum is internal, so the generated companion class is internal too, avoiding CS0060
        Assert.That(type.IsNotPublic, Is.True);
        Assert.That(type.BaseType, Is.EqualTo(typeof(Err<CompanionErrKind>)));

        var pathProperty = type.GetProperty(nameof(CompanionErrKind_NotFound.path));
        Assert.That(pathProperty, Is.Not.Null);
        Assert.That(pathProperty.CanWrite, Is.False);
        Assert.That(pathProperty.PropertyType, Is.EqualTo(typeof(string)));
    }

    [Test]
    public void MessageAndArgumentsTest()
    {
        var err = new CompanionErrKind_NotFound("/tmp/a.txt");

        Assert.That(err.kind, Is.EqualTo(CompanionErrKind.NotFound));
        Assert.That(err.path, Is.EqualTo("/tmp/a.txt"));
        Assert.That(err.message, Is.EqualTo("File /tmp/a.txt Do Not Exist"));
        Assert.That(err.causedBy, Is.Null);
        Assert.That(err.exception, Is.Null);
    }

    [Test]
    public void MultipleArgumentsAndFormatSpecifierTest()
    {
        var err = new CompanionErrKind_Timeout("/tmp/b.txt", 1.5);

        Assert.That(err.kind, Is.EqualTo(CompanionErrKind.Timeout));
        Assert.That(err.path, Is.EqualTo("/tmp/b.txt"));
        Assert.That(err.timeout, Is.EqualTo(1.5));
        Assert.That(err.message, Is.EqualTo($"Read /tmp/b.txt Timeout After {1.5:F2}s"));
    }

    [Test]
    public void MessageOverrideTest()
    {
        var err = new CompanionErrKind_NotFound("/tmp/a.txt", msg: "custom message");

        Assert.That(err.message, Is.EqualTo("custom message"));
        Assert.That(err.path, Is.EqualTo("/tmp/a.txt"));
    }

    [Test]
    public void EscapedTemplateTest()
    {
        var err = new CompanionErrKind_Escaped();

        Assert.That(err.message, Is.EqualTo("Literal {brace}, quote \" and back\\slash"));
    }

    [Test]
    public void KeywordArgumentNameTest()
    {
        var err = new CompanionErrKind_Keyword("click");

        // ReSharper disable once ArrangeThisQualifierIsRedundant
        Assert.That(err.@event, Is.EqualTo("click"));
        Assert.That(err.message, Is.EqualTo("event = click"));
    }

    [Test]
    public void CustomCompanionNameTest()
    {
        var err = new CustomNamedCompanion(42);

        Assert.That(err, Is.InstanceOf<Err<CompanionErrKind>>());
        Assert.That(err.kind, Is.EqualTo(CompanionErrKind.CustomNamed));
        Assert.That(err.value, Is.EqualTo(42));
        Assert.That(err.message, Is.EqualTo("custom named 42"));
    }

    [Test]
    public void CausedByAndExceptionTest()
    {
        var rootCause = new CompanionErrKind_NotFound("/tmp/a.txt");
        var exception = new InvalidOperationException("boom");
        var err = new CompanionErrKind_Timeout("/tmp/b.txt", 0.5, causedBy: rootCause, ex: exception);

        Assert.That(err.causedBy, Is.SameAs(rootCause));
        Assert.That(err.exception, Is.SameAs(exception));

        Assert.That(err.CausedByException(out var found), Is.True);
        Assert.That(found, Is.SameAs(exception));

        string text = err.ToString();
        Assert.That(text, Does.Contain(CompanionErrKind.Timeout.ToString()));
        Assert.That(text, Does.Contain("File /tmp/a.txt Do Not Exist"));
        Assert.That(text, Does.Contain("boom"));
    }

    [Test]
    public void CallerInfoIsCapturedTest()
    {
        // The companion constructor already has optional [CallerMemberName] parameters, no need to pass them
        var err = new CompanionErrKind_NotFound("/tmp/a.txt");
        string expectedMember = CurrentMember();

        err.AddNote("a note");
        string text = err.ToString();

        Assert.That(text, Does.Contain("At: " + expectedMember));
        Assert.That(text, Does.Contain("a note"));
    }

    [Test]
    public void PanicTest()
    {
        var err = new CompanionErrKind_NotFound("/tmp/a.txt");

        Assert.Catch<ManualPanicException>(() => throw err.Panic());
    }

    [Test]
    public void ImplicitConversionToResultTest()
    {
        Result<string, CompanionErrKind> result = new CompanionErrKind_NotFound("/tmp/a.txt");

        Assert.That(result.isOK, Is.False);
        Assert.That(result.err, Is.InstanceOf<CompanionErrKind_NotFound>());
        Assert.That(((CompanionErrKind_NotFound)result.err).path, Is.EqualTo("/tmp/a.txt"));
    }

    [Test]
    public void CastToCompanionTest()
    {
        Err<CompanionErrKind> err = new CompanionErrKind_NotFound("/tmp/a.txt");
        var casted = err.CastTo<CompanionErrKind_NotFound>();

        Assert.That(casted.path, Is.EqualTo("/tmp/a.txt"));
    }
}